style.css:
.card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  font-size: 18px; line-height: 1.5; padding: 28px 18px;
  color: #1c1c1e; background: #f4f4f7; text-align: left;
}
.nightMode .card, .card.nightMode { color: #e6e6ea; background: #1b1b1d; }
.card-body { max-width: 620px; margin: 0 auto; }

/* ---- Front ---- */
.kind {
  display: inline-block; font-size: 12.5px; font-weight: 600;
  padding: 4px 11px; border-radius: 999px; margin-bottom: 16px;
  color: #3a3a3c; background: rgba(142,142,147,.18);
}
.nightMode .kind { color: #d1d1d6; }
.k-rule    { color: #0a58ca; background: rgba(10,132,255,.13); }
.k-form    { color: #8a4b00; background: rgba(255,149,0,.15); }
.k-choose  { color: #6b2fb3; background: rgba(175,82,222,.14); }
.k-meaning { color: #00707a; background: rgba(48,176,199,.15); }
.k-fix     { color: #b3261e; background: rgba(255,59,48,.12); }
.k-listen  { color: #0a7d33; background: rgba(52,199,89,.15); }
.k-speak   { color: #a8326e; background: rgba(255,45,85,.12); }
.nightMode .k-rule { color: #64a8ff; } .nightMode .k-form { color: #ffb454; }
.nightMode .k-choose { color: #d29bff; } .nightMode .k-meaning { color: #6fd6e6; }
.nightMode .k-fix { color: #ff8a80; } .nightMode .k-listen { color: #64e58a; }
.nightMode .k-speak { color: #ff8ab3; }

.q { font-size: 26px; font-weight: 650; line-height: 1.35; }
.q-en { font-size: 25px; font-weight: 600; line-height: 1.4; }
.q-vi { font-size: 24px; font-weight: 650; line-height: 1.38; }
.ask { margin-top: 12px; font-size: 18px; font-weight: 600; color: #00707a; }
.nightMode .ask { color: #6fd6e6; }
.task { margin-top: 12px; font-size: 17px; font-weight: 600; color: #a8326e; }
.nightMode .task { color: #ff8ab3; }
.hint { margin-top: 8px; font-size: 16px; color: #8e8e93; }
.ctx { margin-top: 8px; font-size: 15px; color: #8e8e93; font-style: italic; }
.blank {
  display: inline-block; min-width: 76px; border-bottom: 2.5px solid #ff9500;
  margin: 0 3px; height: 1.05em; vertical-align: baseline;
}
.opts { margin-top: 14px; display: flex; flex-wrap: wrap; gap: 8px; }
.opt {
  font-size: 17px; padding: 6px 14px; border-radius: 10px;
  border: 1.5px solid rgba(175,82,222,.35); background: rgba(175,82,222,.06);
}
.instr {
  margin-top: 26px; padding-top: 12px; border-top: 1px dashed rgba(142,142,147,.3);
  font-size: 13px; color: #9a9aa0;
}
.listen-audio { margin-top: 6px; }
.typebox { margin-top: 14px; }
.typebox input, #typeans {
  width: 100%; box-sizing: border-box; font-size: 19px; padding: 10px 12px;
  border-radius: 10px; border: 1.5px solid rgba(142,142,147,.4); background: transparent; color: inherit;
}
code#typeans { display: block; white-space: pre-wrap; font-family: inherit; }

/* ---- Back ---- */
.recap { opacity: .6; }
.recap .instr { display: none; }
.recap .q, .recap .q-en, .recap .q-vi { font-size: 19px; }
.recap .kind { margin-bottom: 10px; }
hr#answer { border: none; border-top: 1px solid rgba(142,142,147,.25); margin: 22px 0 18px; }
.ans {
  background: rgba(52,199,89,.10); border: 1px solid rgba(52,199,89,.26);
  border-left: 4px solid #34c759; border-radius: 14px; padding: 14px 17px;
  font-size: 22px; font-weight: 600; line-height: 1.4;
}
.ans-sm { font-size: 18px; font-weight: 500; }
.ans .vi { display: block; margin-top: 6px; font-size: 15px; font-weight: 400; color: #6e6e73; }
.nightMode .ans .vi { color: #a8a8ae; }
.hl { color: #0a7d33; background: rgba(52,199,89,.18); padding: 0 3px; border-radius: 4px; }
.nightMode .hl { color: #64e58a; }
.wrong { margin-bottom: 10px; font-size: 17px; color: #8e8e93; }
.wrong .del { color: #c0392b; text-decoration: line-through; text-decoration-thickness: 2px; }
.nightMode .wrong .del { color: #ff8a80; }
.ok { font-size: 15px; font-weight: 600; color: #0a7d33; margin-bottom: 6px; }
.why {
  margin-top: 14px; font-size: 15.5px; line-height: 1.5; color: #3a3a3c;
  background: rgba(255,204,0,.13); border-radius: 10px; padding: 10px 13px;
}
.nightMode .why { color: #e6e6ea; background: rgba(255,204,0,.10); }
.why::before { content: "💡 "; }
.check {
  margin-top: 14px; font-size: 15px; line-height: 1.5;
  border: 1.5px dashed rgba(255,45,85,.35); border-radius: 10px; padding: 9px 13px;
}
.check::before { content: "✔ Chấm Good nếu: "; font-weight: 600; color: #a8326e; }
.nightMode .check::before { color: #ff8ab3; }
.ex { margin-top: 12px; font-size: 17px; font-style: italic; color: #3a3a3c; }
.nightMode .ex { color: #d1d1d6; }
.say-audio { margin-top: 10px; }
.unit {
  margin-top: 22px; font-size: 12px; font-weight: 600; letter-spacing: .04em;
  text-transform: uppercase; color: #aeaeb2;
}

.replay-button svg { width: 34px; height: 34px; }
.replay-button svg circle { fill: #34c759; }
.replay-button svg path { fill: #ffffff; }
